强制模型调用工具："required"

当工作流必须走工具链路时使用——例如强制检索、强制查询数据库，不允许模型凭记忆直接作答：
{
  "tool_choice": "required"
}
模型在本轮必须至少调用一个工具。使用时请确保请求中声明了可调用的工具。一个典型用法是工具搜索模式：首轮用 "required" 强制模型调用 search_tools，检索完成后恢复 "auto"，详见 Kimi K3 API 工具调用最佳实践。

指导模型使用参考文本来回答问题

如果您可以提供一个包含与当前查询相关的可信信息的模型，那么就可以指导模型使用所提供的信息来回答问题
{
  "messages": [
    {"role": "system", "content": "使用提供的文章（用三引号分隔）回答问题。如果答案在文章中找不到，请写\"我找不到答案。\""},
    {"role": "user", "content": "<请插入文章，每篇文章用三引号分隔>"}
  ]
}

messages = [
    {
        "role": "system",
        "content": "你是 Kimi，由 Moonshot AI 提供的人工智能助手，你更擅长中文和英文的对话。你会为用户提供安全，有帮助，准确的回答。同时，你会拒绝一切涉及恐怖主义，种族歧视，黄色暴力等问题的回答。Moonshot AI 为专有名词，不可翻译成其他语言。",
    },
    {
        "role": "system",
        "content": file_content, # <-- 这里，我们将抽取后的文件内容（注意是文件内容，而不是文件 ID）放置在请求中
    },
    {"role": "user", "content": "请简单介绍 moonshot.pdf 的具体内容"},
]

completion = client.chat.completions.create(
  model="kimi-k3",
  messages=messages
)
print(completion.choices[0].message)
const OpenAI = require("openai");
const fs = require("fs")
const client = new OpenAI({
    apiKey: process.env.MOONSHOT_API_KEY,
    baseURL: "https://api.moonshot.cn/v1",
});
async function main() {
    // moonshot.pdf 是一个示例文件, 我们支持 pdf, doc, txt 等文本类格式的内容抽取；图片文件不再支持内容抽取，
    // 图片理解请使用 purpose="image" 上传图片（参见使用视觉模型指南）
    let file_object = await client.files.create({
        file: fs.createReadStream("moonshot.pdf"),
        purpose: "file-extract"
    })
    // 获取结果
    // file_content = client.files.retrieve_content(file_id=file_object.id)
    // 注意，之前 retrieve_content api 在最新版本标记了 warning, 可以用下面这行代替
    // 如果是旧版本，可以用 retrieve_content
    let file_content = await (await client.files.content(file_object.id)).text()
    // 把它放进请求中
    let messages = [
        {
            "role": "system",
            "content": "你是 Kimi，由 Moonshot AI 提供的人工智能助手，你更擅长中文和英文的对话。你会为用户提供安全，有帮助，准确的回答。同时，你会拒绝一切涉及恐怖主义，种族歧视，黄色暴力等问题的回答。Moonshot AI 为专有名词，不可翻译成其他语言。",
        },
        {
            "role": "system",
            "content": file_content,
        },
        {"role": "user", "content": "请简单介绍 moonshot.pdf 的具体内容"},
    ]
    const completion = await client.chat.completions.create({
        model: "kimi-k3",
        messages: messages
    });
    console.log(completion.choices[0].message.content);
}
main();
让我们回顾一下文件问答的基本步骤及注意事项：
通过文件上传接口 /v1/files 或 SDK 中的 files.create API 将文件上传至 Kimi 服务器；
通过文件抽取接口 /v1/files/{file_id} 或 SDK 中的 files.content API 获取文件内容，此时获取的文件内容已经对齐了我们推荐的模型易于理解的格式；
将文件抽取后（已经对齐格式的）文件内容（而不是文件 id），以系统提示词 system prompt 的形式放置在 messages 列表中；
开始你对文件内容的提问；
再次注意，请将文件内容放置在 prompt 中，而不是文件的 file_id。

对话中的网络搜索允许 Completions API 调用搜索引擎，将实时网络检索结果与 GLM 的生成能力相结合，提供最新且可验证的答案。

API文档： 对话中的网络搜索 示例：财经分析摘要

